// Stage 1: robust static offset estimation between a reference and target
// signal. Blockwise GCC-PHAT, confidence-gated, combined with a weighted
// median so a handful of bad blocks (silence, noise bursts) can't skew it.

const { gccPhat, paddedSlice } = require("./gccPhat.js");

function rmsOf(x, from = 0, to = x.length) {
  let e = 0;
  for (let i = from; i < to; i++) e += x[i] * x[i];
  const n = to - from;
  return n > 0 ? Math.sqrt(e / n) : 0;
}

const db = (lin) => 20 * Math.log10(lin + 1e-30);

/**
 * Silence threshold scaled to the material rather than a fixed dBFS value.
 * A conservatively-recorded lav can sit 30 dB below a fixed -50 dBFS gate,
 * which would gate out every window and fail the pair as "no correlation".
 * The gate sits `relDb` below the signal's own average level, bounded by an
 * absolute floor so a near-silent input can't drag it into the noise.
 */
function adaptiveGateDb(signal, { relDb = 25, floorDb = -85, ceilDb = -35 } = {}) {
  const overall = db(rmsOf(signal));
  const gate = overall - relDb;
  if (gate < floorDb) return floorDb;
  if (gate > ceilDb) return ceilDb;
  return gate;
}

function weightedMedian(pairs) {
  // pairs: [{ v, w }]
  const sorted = [...pairs].sort((a, b) => a.v - b.v);
  const total = sorted.reduce((s, p) => s + p.w, 0);
  let acc = 0;
  for (const p of sorted) {
    acc += p.w;
    if (acc >= total / 2) return p.v;
  }
  return sorted.length ? sorted[sorted.length - 1].v : 0;
}

/**
 * @returns {{ ok: boolean, reason?: string, offsetSamples?: number, confidence?: number,
 *             blocks: Array<{t0:number,lag:number,peakRatio:number,rms:number,used:boolean}> }}
 */
function estimateStaticOffset(ref, tgt, opts) {
  const {
    sampleRate,
    maxShiftMs = 500,
    blockSec = 1.0,
    hopSec = 0.5,
    confidenceGate = 1.5,
    rmsGateDb = null, // null => derive from the reference's own level
    exclusionMs = 2,
    minConfidentBlocks = 3,
    bandWeights = null,
    // Genuine pairs may spread their block lags by the real dynamic drift, so
    // lag agreement is only meaningful at the maxDrift scale.
    agreementToleranceMs = 15,
    // Cap on how many blocks to correlate, spread evenly across the clip.
    // null keeps the fixed hopSec stride, whose cost grows with clip length.
    maxBlocks = null,
    // Centre the +/-maxShiftMs window on this lag rather than on zero, so a
    // narrow window can refine an offset already known roughly. Reported lags
    // stay absolute.
    centerSamples = 0,
  } = opts;
  if (!sampleRate) throw new Error('sampleRate required');

  const N = Math.round(blockSec * sampleRate);
  let hop = Math.round(hopSec * sampleRate);
  const L = Math.round((maxShiftMs / 1000) * sampleRate);
  const exclusion = Math.round((exclusionMs / 1000) * sampleRate);
  const centre = Math.round(centerSamples);
  const len = Math.min(ref.length, tgt.length);
  const blocks = [];
  const gateDb = rmsGateDb === null ? adaptiveGateDb(ref) : rmsGateDb;

  if (len < N) return { ok: false, reason: 'too-short', blocks };

  // A weighted median over 24 blocks spread across the clip is no less robust
  // than one over the 599 a 5-minute clip yields at a fixed 0.5 s hop, and it
  // makes this stage cost the same whatever the clip length. Callers that need
  // the dense grid (because the sparse one found too little to agree on) ask
  // for it by passing maxBlocks: null.
  if (maxBlocks !== null && maxBlocks > 1) {
    const natural = Math.floor((len - N) / hop) + 1;
    if (natural > maxBlocks) hop = Math.floor((len - N) / (maxBlocks - 1));
  }

  for (let t0 = 0; t0 + N <= len; t0 += hop) {
    const refBlock = ref.subarray(t0, t0 + N);
    const rms = rmsOf(refBlock);
    if (db(rms) < gateDb) {
      blocks.push({ t0, lag: 0, peakRatio: 0, rms, used: false });
      continue;
    }
    const slice = paddedSlice(tgt, t0 - L + centre, N + 2 * L);
    const r = gccPhat(refBlock, slice, L, { exclusionSamples: exclusion, bandWeights });
    blocks.push({ t0, lag: r.bestLag + centre, peakRatio: r.peakRatio, rms, used: false });
  }

  const confident = blocks.filter((b) => b.peakRatio >= confidenceGate);
  if (confident.length < minConfidentBlocks) {
    return { ok: false, reason: 'no-correlation', blocks };
  }
  for (const b of confident) b.used = true;

  const offsetSamples = weightedMedian(
    confident.map((b) => ({ v: b.lag, w: (b.peakRatio - 1) * b.rms }))
  );

  // A true match has confident blocks agreeing on one lag; spurious envelope
  // correlations between unrelated signals scatter across the search range.
  const tol = (agreementToleranceMs / 1000) * sampleRate;
  const agreeing = confident.filter((b) => Math.abs(b.lag - offsetSamples) <= tol).length;
  if (agreeing < minConfidentBlocks || agreeing / confident.length < 0.5) {
    return { ok: false, reason: 'no-correlation', blocks };
  }
  const confidence = agreeing / blocks.filter((b) => db(b.rms) >= gateDb).length;

  return { ok: true, offsetSamples, confidence, blocks };
}

module.exports = { rmsOf, db, adaptiveGateDb, weightedMedian, estimateStaticOffset };
